&lt;/ul&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot; data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;32&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Work in a team environment to start up, shut down, monitor, inspect, operate, and adjust plant equipment while meeting customer expectations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559737&amp;quot;:515,&amp;quot;469777462&amp;quot;:[720],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot; data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;32&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Analyze trends in various plant parameters such as temperature, pressure, pH, and flow to respond appropriately to process deviations with the goal to maintain product specifications and safe conditions&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559737&amp;quot;:82,&amp;quot;469777462&amp;quot;:[720],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot; data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;32&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Operate production equipment including, but not limited to, holding tanks, centrifugal pumps, leaf filters, heat exchangers, electrodeposition machines, metering pumps, wastewater treatment systems, utility manifolds, centrifuges, filter presses, kilns, bulk material conveyance, evaporators, crystallizers,&amp;nbsp;mills, mixers,&amp;nbsp;and logistical equipment.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559737&amp;quot;:223,&amp;quot;469777462&amp;quot;:[720],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot; data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;32&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Perform routine product samples to submit for analysis and verify results are within expected parameters.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559737&amp;quot;:474,&amp;quot;469777462&amp;quot;:[720],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot; data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;32&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;7&quot; data-aria-level=&quot;1&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Work with Engineering and Manufacturing teams to ensure instructions are executed and communicated effectively across shifts.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559737&amp;quot;:322,&amp;quot;469777462&amp;quot;:[720],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
