&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ability to bend, twist, lift, and carry materials and tools (up to approximately 50 lbs).&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
