&lt;p class=&quot;font-claude-response-body break-words whitespace-normal&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Desired Qualifications:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
